"use client";

import React, { useState } from "react";
import { 
  FileText, ShieldCheck, Clock, AlertTriangle, 
  UserCheck, Share2, Printer, PenTool, Search, Plus
} from "lucide-react";
import Badge from "@/components/ui/badge/Badge";

/* ========================
   ENHANCED TYPES
======================== */
interface SmartDocument {
  id: string;
  name: string;
  type: string;
  status: "Verified" | "Action Required" | "Signed" | "Expired";
  integrity: number; // 0 to 100% (OCR match score)
  expiry?: string;
  isSensitive: boolean;
}

const smartDocs: SmartDocument[] = [
  { id: "1", name: "Passport_Final.pdf", type: "Identity", status: "Verified", integrity: 98, expiry: "2029-05-12", isSensitive: true },
  { id: "2", name: "FY25_Form16.pdf", type: "Tax", status: "Signed", integrity: 100, isSensitive: true },
  { id: "3", name: "Work_Policy_v2.pdf", type: "Company", status: "Action Required", integrity: 100, isSensitive: false },
  { id: "4", name: "Old_Visa_Copy.pdf", type: "Travel", status: "Expired", integrity: 85, expiry: "2024-12-01", isSensitive: false },
];

export default function EliteDocumentHub() {
  return (
    <div className="p-8 space-y-8 bg-[#F8F9FB] dark:bg-[#06080F] min-h-screen">
      
      {/* 1. DOCUMENT HEALTH HUD */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white dark:bg-gray-900 rounded-[2.5rem] p-8 shadow-sm border border-gray-100 dark:border-gray-800 flex justify-between items-center">
          <div className="space-y-2">
            <h2 className="text-3xl font-black tracking-tighter">Document Integrity</h2>
            <p className="text-gray-500 text-sm font-medium">Your profile is 85% compliant. <span className="text-brand-600 underline cursor-pointer">Fix 2 issues.</span></p>
          </div>
          <div className="flex -space-x-4">
             {[1,2,3,4].map(i => (
               <div key={i} className="w-12 h-12 rounded-full border-4 border-white dark:border-gray-900 bg-gray-100 flex items-center justify-center overflow-hidden">
                 <FileText className="text-gray-400 w-5 h-5" />
               </div>
             ))}
          </div>
        </div>
        <div className="bg-brand-600 rounded-[2.5rem] p-8 text-white flex flex-col justify-between">
           <p className="text-xs font-bold uppercase tracking-widest opacity-80">Quick Action</p>
           <h3 className="text-xl font-bold">Need a Certificate?</h3>
           <button className="mt-4 bg-white text-brand-600 py-3 rounded-2xl font-black text-xs uppercase shadow-xl hover:scale-105 transition-all">Generate Now</button>
        </div>
      </div>

      {/* 2. THE INTELLIGENT LIST */}
      <div className="bg-white dark:bg-gray-900 rounded-[3rem] shadow-xl border border-gray-100 dark:border-gray-800 overflow-hidden">
        <div className="p-8 border-b border-gray-50 dark:border-gray-800 flex justify-between items-center">
           <h3 className="text-xl font-black">Managed Archives</h3>
           <div className="flex gap-4">
              <div className="relative">
                <Search className="absolute left-3 top-2.5 text-gray-400 w-4 h-4" />
                <input placeholder="Search encrypted files..." className="pl-10 pr-4 py-2 bg-gray-50 dark:bg-gray-800 border-none rounded-xl text-sm w-64" />
              </div>
              <button className="bg-gray-900 text-white dark:bg-brand-600 px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2">
                <Plus className="w-4 h-4" /> Secure Upload
              </button>
           </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50/50 dark:bg-gray-800/50 text-[10px] uppercase font-black text-gray-400">
              <tr>
                <th className="px-8 py-4">Document / Metadata</th>
                <th className="px-8 py-4">Status</th>
                <th className="px-8 py-4">Security</th>
                <th className="px-8 py-4">OCR Score</th>
                <th className="px-8 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-gray-800">
              {smartDocs.map((doc) => (
                <tr key={doc.id} className="group hover:bg-gray-50/50 transition-all">
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-4">
                      <div className="p-3 bg-gray-100 dark:bg-gray-800 rounded-2xl text-gray-500 group-hover:text-brand-600 transition-colors">
                        <FileText className="w-6 h-6" />
                      </div>
                      <div>
                        <h4 className="text-sm font-black text-gray-900 dark:text-white">{doc.name}</h4>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">{doc.type} {doc.expiry && `• Exp: ${doc.expiry}`}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <StatusIndicator status={doc.status} />
                  </td>
                  <td className="px-8 py-6">
                    {doc.isSensitive ? (
                      <div className="flex items-center gap-1 text-brand-600">
                        <ShieldCheck className="w-4 h-4" /> <span className="text-[10px] font-black uppercase">AES-256</span>
                      </div>
                    ) : (
                      <span className="text-[10px] font-bold text-gray-400 uppercase">Standard</span>
                    )}
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-2">
                      <div className="w-12 h-1 bg-gray-100 rounded-full overflow-hidden">
                        <div className="h-full bg-emerald-500" style={{ width: `${doc.integrity}%` }} />
                      </div>
                      <span className="text-[10px] font-bold text-gray-500">{doc.integrity}%</span>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex justify-end gap-3">
                      <button title="Share Privately" className="p-2 hover:bg-brand-50 rounded-lg text-gray-400 hover:text-brand-600 transition-all"><Share2 size={16}/></button>
                      <button title="e-Sign" className="p-2 hover:bg-brand-50 rounded-lg text-gray-400 hover:text-brand-600 transition-all"><PenTool size={16}/></button>
                      <button title="Print" className="p-2 hover:bg-brand-50 rounded-lg text-gray-400 hover:text-brand-600 transition-all"><Printer size={16}/></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function StatusIndicator({ status }: { status: string }) {
  const styles: any = {
    Verified: "bg-emerald-50 text-emerald-600",
    Signed: "bg-blue-50 text-blue-600",
    "Action Required": "bg-amber-50 text-amber-600 animate-pulse",
    Expired: "bg-red-50 text-red-600",
  };
  return (
    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${styles[status]}`}>
      {status}
    </span>
  );
}